"""Page arithmetic for list pages."""


def page_count(total_items, per_page):
    """Number of pages needed for the items.

    20 items at 10 per page is 2 pages, 21 items is 3. Zero items is 1 page,
    because the site always shows one page.
    """
    if per_page < 1:
        raise ValueError("per_page must be at least 1")
    if total_items < 0:
        raise ValueError("total_items must be at least 0")
    if total_items == 0:
        return 1
    return (total_items + per_page - 1) // per_page


def page_slice(total_items, per_page, page):
    """(start, end) indexes of the items on a page. Pages are numbered from 1.

    The last page may be short. A page below 1 or above ``page_count`` raises
    ``ValueError``.
    """
    if per_page < 1:
        raise ValueError("per_page must be at least 1")
    if total_items < 0:
        raise ValueError("total_items must be at least 0")
    pages = page_count(total_items, per_page)
    if page < 1 or page > pages:
        raise ValueError("no such page")
    start = (page - 1) * per_page
    end = min(start + per_page, total_items)
    return start, end


def page_window(total_items, per_page, page, size=5):
    """Page numbers to show in the pager, centred on the current page.

    The window lists ``size`` consecutive page numbers, or all pages when there
    are fewer than ``size``. The current page sits in the middle when it can;
    with an even ``size`` the extra page goes after the current one. Near the
    first or last page the window is shifted to stay inside 1 to ``page_count``
    while keeping its full length.
    """
    if per_page < 1:
        raise ValueError("per_page must be at least 1")
    if total_items < 0:
        raise ValueError("total_items must be at least 0")
    if size < 1:
        raise ValueError("size must be at least 1")
    pages = page_count(total_items, per_page)
    if page < 1 or page > pages:
        raise ValueError("no such page")
    if pages <= size:
        return list(range(1, pages + 1))
    before = (size - 1) // 2
    after = size // 2
    first = page - before
    last = page + after
    if first < 1:
        first = 1
        last = first + size - 1
    if last > pages:
        last = pages
        first = last - size + 1
    return list(range(first, last + 1))
